// Codegen: primitives' declarative `fields` → typed Zod SOURCE (P2b;
// plans/primitive-componentization.md §2.3). Emits schema/generated/objects.generated.ts
// with one `export const <type> = z.object({...}).strict()` per primitive, so the
// schema, its TS type (z.infer), and the docs share ONE source. houseConfig imports
// these into the object union — no hand-written schema per primitive.
//
//   npx tsx scripts/gen-primitives.mjs           # (re)write the generated file
//   npx tsx scripts/gen-primitives.mjs --check    # exit 1 if stale (CI guard)

import { writeFileSync, readFileSync, existsSync, mkdirSync } from "node:fs";
import path from "node:path";
import url from "node:url";
import { PRIMITIVE_FIELD_DECLS } from "../src/schema/fields/index.ts";
import { fieldsToZodSource } from "../src/registry/fieldSchema.ts";

const here = path.dirname(url.fileURLToPath(import.meta.url));
const OUT = path.resolve(here, "../src/schema/generated/objects.generated.ts");

export function renderGenerated() {
  const header = `// AUTO-GENERATED by scripts/gen-primitives.mjs — DO NOT EDIT.
// Generated from schema/fields/*. Regenerate: npm run gen-primitives.
// Each primitive's Zod schema is emitted from its declarative \`fields\` so the
// schema, its TS type (z.infer), and the docs share one source.
import { z } from "zod";
`;
  const body = PRIMITIVE_FIELD_DECLS.map((d) => {
    // Primitive-level prose becomes the const's leading comment; the data-model doc
    // generator reads it as the object's description (keeps docs sourced from fields).
    const lead = d.doc ? `// ${d.doc}\n` : "";
    return `\n${lead}export const ${d.type} = ${fieldsToZodSource(d.type, d.fields)};\n`;
  }).join("");
  return header + body;
}

// Run only when invoked directly (not when imported by the drift-guard test).
if (process.argv[1] && path.resolve(process.argv[1]) === url.fileURLToPath(import.meta.url)) {
  const content = renderGenerated();
  if (process.argv.includes("--check")) {
    const cur = existsSync(OUT) ? readFileSync(OUT, "utf8") : "";
    if (cur !== content) {
      console.error("✗ objects.generated.ts is STALE — run: npm run gen-primitives");
      process.exit(1);
    }
    console.log("✓ generated schemas up to date");
  } else {
    mkdirSync(path.dirname(OUT), { recursive: true });
    writeFileSync(OUT, content);
    console.log(`wrote ${PRIMITIVE_FIELD_DECLS.length} generated schema(s) → ${path.relative(path.resolve(here, ".."), OUT)}`);
  }
}
